import{_ as r,y as i,a as g,o as l,a2 as s,g as e,D as o,I as a}from"./chunks/framework.DCcmcJcL.js";const C=JSON.parse('{"title":"Campaigns","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/campaigns.md","filePath":"marketing/campaigns.md","lastUpdated":1789441803000}'),h={name:"marketing/campaigns.md"};function p(m,t,u,d,c,b){const n=i("ImagePopup");return l(),g("div",null,[t[3]||(t[3]=s('<h1 id="campaigns" tabindex="-1">Campaigns <a class="header-anchor" href="#campaigns" aria-label="Permalink to &quot;Campaigns&quot;">​</a></h1><p>A campaign sends a marketing email to a group of customers on a set day. It brings three things together: the <a href="./email-templates.html">email template</a> to send, the <a href="./events.html">event</a> that sets the day, and the customer group that receives it.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>An active email template</strong>, created under <strong>Marketing &gt;&gt; Communications &gt;&gt; Email Templates</strong> with <strong>Status</strong> set to <strong>Active</strong>.</li><li><strong>An event</strong>, created under <strong>Marketing &gt;&gt; Communications &gt;&gt; Events</strong>, or the built-in <strong>Birthday</strong> event.</li><li><strong>Newsletter subscribers.</strong> Campaigns go to people who subscribed to your newsletter. See <a href="./newsletter-subscription.html">Newsletter subscriptions</a>.</li><li><strong>Scheduled tasks and a queue worker.</strong> Campaigns are sent by a daily scheduled task, and the emails go out through a background queue. Your developer or host sets both up for Bagisto. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</li><li><strong>Email settings.</strong> The sender name and address come from <a href="./../configure/email-settings.html">Email Settings</a>.</li></ul><h2 id="create-a-campaign" tabindex="-1">Create a campaign <a class="header-anchor" href="#create-a-campaign" aria-label="Permalink to &quot;Create a campaign&quot;">​</a></h2>',5)),e("ol",null,[t[1]||(t[1]=s("<li><p>Go to <strong>Marketing &gt;&gt; Communications &gt;&gt; Campaigns</strong>.</p></li><li><p>Click <strong>Create Campaign</strong>.</p></li><li><p>Under <strong>General</strong>, enter the <strong>Name</strong>.</p></li><li><p>Enter the <strong>Subject</strong>, the subject line of the email.</p></li><li><p>Choose the <strong>Event</strong>.</p></li><li><p>Choose the <strong>Email Template</strong>. The list shows only active templates.</p></li><li><p>Under <strong>Setting</strong>, choose the <strong>Channel</strong>.</p></li><li><p>Choose the <strong>Customer Group</strong>.</p></li>",8)),e("li",null,[t[0]||(t[0]=e("p",null,[a("Switch "),e("strong",null,"Status"),a(" on.")],-1)),o(n,{src:"/images/marketing/campaign-create.png",alt:"The Create Campaign page with the Autumn Sale event, the Autumn Newsletter template, the Default channel and the General group"})]),t[2]||(t[2]=e("li",null,[e("p",null,[a("Click "),e("strong",null,"Save Campaign"),a(".")])],-1))]),t[4]||(t[4]=s('<p>You see &quot;Campaign created successfully.&quot; The <strong>Channel</strong> doesn&#39;t limit who receives the email.</p><h2 id="when-campaigns-are-sent" tabindex="-1">When campaigns are sent <a class="header-anchor" href="#when-campaigns-are-sent" aria-label="Permalink to &quot;When campaigns are sent&quot;">​</a></h2><p>Once a day, at midnight server time, Bagisto sends every campaign that:</p><ul><li>has <strong>Status</strong> switched on,</li><li>uses an email template whose <strong>Status</strong> is <strong>Active</strong>, and</li><li>uses an event dated today, or the <strong>Birthday</strong> event.</li></ul><p>Who receives the email depends on the <strong>Customer Group</strong>:</p><table tabindex="0"><thead><tr><th>Customer Group</th><th>Who receives the email</th></tr></thead><tbody><tr><td><strong>General</strong>, <strong>Wholesale</strong> or another customer group</td><td>Customers in that group whose account has the newsletter option switched on</td></tr><tr><td><strong>Guest</strong></td><td>People on the <strong>Newsletter Subscriptions</strong> list whose entry isn&#39;t linked to a customer account</td></tr><tr><td><strong>General</strong>, <strong>Wholesale</strong> or another customer group, with the <strong>Birthday</strong> event</td><td>Customers in that group whose account has the newsletter option switched on and whose birthday is today</td></tr></tbody></table><p>Someone who subscribed in the storefront footer while signed out counts as a guest until they create an account with that email address. The emails are queued and sent in the background, so a long list can take a while to deliver.</p><div class="warning custom-block"><p class="custom-block-title">Check the list before a Guest campaign</p><p>Before a <strong>Guest</strong> campaign&#39;s event date, open <strong>Marketing &gt;&gt; Communications &gt;&gt; Newsletter Subscriptions</strong> and delete the entries of people who asked to unsubscribe, rather than only setting <strong>Subscribed</strong> to <strong>False</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">There&#39;s no test send</p><p>To try a campaign, use an event dated today and a customer group that holds only your own test account.</p></div><h2 id="manage-campaigns" tabindex="-1">Manage campaigns <a class="header-anchor" href="#manage-campaigns" aria-label="Permalink to &quot;Manage campaigns&quot;">​</a></h2><p>The <strong>Campaigns</strong> list shows each campaign&#39;s <strong>ID</strong>, <strong>Name</strong>, <strong>Subject</strong> and <strong>Status</strong>, with icons to edit and delete it. To stop a campaign without deleting it, open it and switch <strong>Status</strong> off.</p>',11)),o(n,{src:"/images/marketing/campaigns.png",alt:"The Campaigns list with the Autumn Sale Newsletter campaign"})])}const _=r(h,[["render",p]]);export{C as __pageData,_ as default};
